WORK=$(cat /tmp/money-consolidation.path) && cd "$WORK" && cat > dump.cjs <<'EOF'
// usage: node dump.cjs <buildDir> <outDir>
// Records renderer / amount-helper output for a fixed input list so two builds can be compared.
const fs = require('node:fs');
const path = require('node:path');
const [buildDir, outDir] = process.argv.slice(2).map(p => path.resolve(p));
fs.mkdirSync(outDir, { recursive: true });

const inputs = [];
for (let n = -200000; n <= 200000; n++) inputs.push(n); // all integer cents, negative, zero, positive
inputs.push(
  -0, 0.5, -0.5, 1.5, -2.5, 12.5, 1e-7, 1e21, -1e21,
  Number.MAX_SAFE_INTEGER, -Number.MAX_SAFE_INTEGER, 2 ** 53 - 2, -(2 ** 53 - 2),
  1e15, -1e15, 123456789012345, -123456789012345, NaN, Infinity, -Infinity,
);

const tryRequire = f => { try { return require(path.join(buildDir, f)); } catch { return null; } };
const inv = tryRequire('invoice.js');
const rep = tryRequire('report.js');
const result = {};
result.renderInvoice = inputs.map(c => inv.renderInvoice('id', c));
result.renderReportAll = [rep.renderReport(inputs.map((c, i) => ({ id: 'r' + i, cents: c })))];
result.renderReportEach = inputs.map(c => rep.renderReport([{ id: 'x', cents: c }]));
result.renderReportEmpty = [rep.renderReport([])];

const oldInv = tryRequire('invoiceAmount.js');   // exists only in the original build
const oldRep = tryRequire('reportAmount.js');    // exists only in the original build
const money = tryRequire('money.js');            // exists only in the new build
if (oldInv) result.invoiceAmount = inputs.map(c => oldInv.invoiceAmount(c));
if (oldRep) result.reportAmount = inputs.map(c => oldRep.reportAmount(c));
if (money) result.formatAmount = inputs.map(c => money.formatAmount(c));

for (const [k, v] of Object.entries(result)) fs.writeFileSync(path.join(outDir, k + '.json'), JSON.stringify(v));
console.log('wrote [' + Object.keys(result).join(', ') + '] for ' + inputs.length + ' inputs');
EOF
cat > compare.cjs <<'EOF'
// usage: node compare.cjs <baselineOutDir> <newOutDir>
const fs = require('node:fs');
const path = require('node:path');
const [a, b] = process.argv.slice(2);
const load = (d, k) => JSON.parse(fs.readFileSync(path.join(d, k + '.json'), 'utf8'));
const pairs = [
  ['renderInvoice', 'renderInvoice'],
  ['renderReportAll', 'renderReportAll'],
  ['renderReportEach', 'renderReportEach'],
  ['renderReportEmpty', 'renderReportEmpty'],
  ['invoiceAmount', 'formatAmount'],
  ['reportAmount', 'formatAmount'],
];
let ok = true;
for (const [ka, kb] of pairs) {
  const x = load(a, ka), y = load(b, kb);
  const same = x.length === y.length && x.every((v, i) => v === y[i]);
  console.log(`${(ka + ' [baseline]').padEnd(32)} vs ${(kb + ' [new]').padEnd(26)} => ${same ? 'IDENTICAL' : 'DIFFERENT'} (${x.length} vs ${y.length} values)`);
  ok = ok && same;
}
console.log(ok ? 'ALL IDENTICAL' : 'MISMATCH FOUND');
process.exit(ok ? 0 : 1);
EOF
node dump.cjs orig/.build baseline && echo "--- sample baseline values ---" && node -e '
const inv = require("./orig/.build/invoice.js"); const rep = require("./orig/.build/report.js");
const ia = require("./orig/.build/invoiceAmount.js"); const ra = require("./orig/.build/reportAmount.js");
for (const c of [0, 1, 5, 99, 100, 123, 1234567, -1, -5, -100, -123, -0]) console.log(String(c).padStart(9), JSON.stringify(ia.invoiceAmount(c)), JSON.stringify(ra.reportAmount(c)), JSON.stringify(inv.renderInvoice("inv", c)));
console.log(JSON.stringify(rep.renderReport([{id:"a",cents:250},{id:"b",cents:0},{id:"c",cents:-1}])));
'

cd /workspace && cat > src/money.ts <<'EOF'
// Formats an amount in integer cents as a sign, whole currency units and exactly
// two fraction digits, with no currency symbol: 123 -> "1.23", -5 -> "-0.05", 0 -> "0.00".
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
cat > src/invoice.ts <<'EOF'
import { formatAmount } from './money';
export function renderInvoice(id: string, cents: number): string { return id + ': $' + formatAmount(cents); }
EOF
cat > src/report.ts <<'EOF'
import { formatAmount } from './money';
export function renderReport(rows: { id: string; cents: number }[]): string {
  return rows.map(row => row.id + ',' + formatAmount(row.cents)).join('\n');
}
EOF
rm src/invoiceAmount.ts src/reportAmount.ts
echo "--- src now ---"; ls -la src; echo "--- grep for old names in src/ and checks/ ---"; grep -rn "invoiceAmount\|reportAmount" src checks || echo "(no references)"; echo "--- diff vs original snapshot ---"; WORK=$(cat /tmp/money-consolidation.path); diff -ru "$WORK/orig/src" src; echo "diff exit: $?"

