// formatAmount (src/money.ts) for positive, zero and negative integer cents.
const { formatAmount } = require('../.build/money');
assert.equal(formatAmount(0), '0.00');
assert.equal(formatAmount(-0), '0.00');
assert.equal(formatAmount(1), '0.01');
assert.equal(formatAmount(99), '0.99');
assert.equal(formatAmount(100), '1.00');
assert.equal(formatAmount(1234567), '12345.67');
assert.equal(formatAmount(Number.MAX_SAFE_INTEGER), '90071992547409.91');
assert.equal(formatAmount(-1), '-0.01');
assert.equal(formatAmount(-100), '-1.00');
assert.equal(formatAmount(-123), '-1.23');
// Every integer cent in a range, against an independent string-based formulation.
for (let cents = -100000; cents <= 100000; cents++) {
  const digits = String(Math.abs(cents)).padStart(3, '0');
  const expected = (cents < 0 ? '-' : '') + digits.slice(0, -2) + '.' + digits.slice(-2);
  assert.equal(formatAmount(cents), expected, `formatAmount(${cents})`);
}

// Renderer output for positive, zero and negative cents, and row order in renderReport.
assert.equal(renderInvoice('inv', 0), 'inv: $0.00');
assert.equal(renderInvoice('inv', -5), 'inv: $-0.05');
assert.equal(renderReport([]), '');
assert.equal(renderReport([{ id: 'a', cents: 250 }, { id: 'b', cents: 0 }, { id: 'c', cents: -1 }]), 'a,2.50\nb,0.00\nc,-0.01');

// The old helper names must not appear anywhere in src/ (file names or contents).
const srcDir = path.join(__dirname, '..', 'src');
for (const file of fs.readdirSync(srcDir)) {
  const text = fs.readFileSync(path.join(srcDir, file), 'utf8');
  assert.doesNotMatch(file + '\n' + text, /\b(?:invoiceAmount|reportAmount)\b/, `${file} still references a removed name`);
}
// Both renderers import the shared helper and call it.
for (const file of ['invoice.ts', 'report.ts']) {
  const text = fs.readFileSync(path.join(srcDir, file), 'utf8');
  assert.match(text, /import\s*\{\s*formatAmount\s*\}\s*from\s*['"]\.\/money['"]/, `${file} must import formatAmount from ./money`);
  assert.match(text, /\bformatAmount\(/, `${file} must call formatAmount`);
}
EOF
sed -i "1a const fs = require('node:fs');\nconst path = require('node:path');" checks/public.cjs && echo "--- public.cjs (new) ---" && cat checks/public.cjs && echo "--- original lines still present verbatim? ---" && diff <(head -n $(wc -l < "$WORK/public.orig.cjs") "$WORK/public.orig.cjs") <(sed -n '1,2p;4,' checks/public.cjs | head -n $(wc -l < "$WORK/public.orig.cjs")) >/dev/null; echo "(manual check follows)"; head -n 6 checks/public.cjs | cat -A | head -6

